-- GENERATED from the tenant mapping (version 8b6af6641b3d903b). Do not edit.
SELECT DISTINCT  -- account.main
    (a.loan_id) AS account_key,
    (a.loan_number) AS account_number,
    CASE (a.product_code) WHEN 'HL' THEN '02' WHEN 'LAP' THEN '03' WHEN 'PL' THEN '05' WHEN 'AL' THEN '01' WHEN 'UCL' THEN '32' WHEN 'TWL' THEN '13' WHEN 'CVL' THEN '17' WHEN 'GL' THEN '07' WHEN 'EDU' THEN '08' WHEN 'CDL' THEN '06' WHEN 'BLU' THEN '61' WHEN 'BLS' THEN '50' WHEN 'MFP' THEN '41' WHEN 'MFB' THEN '40' WHEN 'KCC' THEN '36' WHEN 'LAS' THEN '04' WHEN 'LOC' THEN '37' WHEN 'CC' THEN '10' WHEN 'SCC' THEN '31' WHEN 'CCC' THEN '35' WHEN 'FLC' THEN '16' WHEN 'OD' THEN '12' ELSE (a.product_code) END AS account_type,
    (a.disbursement_date) AS date_opened,
    (a.last_payment_date) AS date_last_payment,
    (a.closed_date) AS date_closed,
    (a.reported_date) AS date_reported,
    (a.sanction_amount) AS high_credit_amount,
    (a.outstanding_amount) AS current_balance,
    (a.overdue_amount) AS amount_overdue,
    (a.days_past_due) AS days_past_due,
    CASE (a.suit_status) WHEN 'NONE' THEN '00' WHEN 'SUIT_FILED' THEN '01' WHEN 'WILFUL' THEN '02' WHEN 'SUIT_WILFUL' THEN '03' ELSE (a.suit_status) END AS suit_filed_status,
    CASE (a.facility_status) WHEN 'RESTRUCT_COVID' THEN '12' WHEN 'WRITTEN_OFF' THEN '02' WHEN 'SETTLED' THEN '03' WHEN 'POST_WO_SETTLED' THEN '04' WHEN 'AUCTIONED_SETTLED' THEN '15' WHEN 'REPOSSESSED_SETTLED' THEN '16' WHEN 'GUARANTEE_INVOKED' THEN '17' ELSE (a.facility_status) END AS credit_facility_status,
    CASE (a.asset_classification) WHEN 'STD' THEN '01' WHEN 'SUB' THEN '02' WHEN 'DBT' THEN '03' WHEN 'LOSS' THEN '04' WHEN 'SMA' THEN '05' ELSE (a.asset_classification) END AS asset_classification,
    (a.collateral_value) AS collateral_value,
    CASE (a.collateral_type) WHEN 'NONE' THEN '00' WHEN 'PROPERTY' THEN '01' WHEN 'GOLD' THEN '02' WHEN 'SHARES' THEN '03' WHEN 'DEPOSIT' THEN '04' WHEN 'MULTIPLE' THEN '05' WHEN 'OTHER' THEN '06' ELSE (a.collateral_type) END AS collateral_type,
    (a.credit_limit) AS credit_limit,
    (a.cash_limit) AS cash_limit,
    (a.interest_rate_percent) AS rate_of_interest,
    (a.tenure_months) AS repayment_tenure,
    (a.emi_amount) AS emi_amount,
    (a.writeoff_total_amount) AS written_off_total,
    (a.writeoff_principal_amount) AS written_off_principal,
    (a.settlement_amount) AS settlement_amount,
    CASE (a.pay_frequency) WHEN 'WEEKLY' THEN '01' WHEN 'FORTNIGHTLY' THEN '02' WHEN 'MONTHLY' THEN '03' WHEN 'QUARTERLY' THEN '04' WHEN 'BULLET' THEN '05' WHEN 'DAILY' THEN '06' WHEN 'HALFYEARLY' THEN '07' WHEN 'YEARLY' THEN '08' WHEN 'ONDEMAND' THEN '09' ELSE (a.pay_frequency) END AS payment_frequency,
    (a.last_payment_amount) AS actual_payment_amount,
    (a.previous_member_code) AS old_member_code,
    (a.previous_member_short_name) AS old_member_short_name,
    (a.previous_loan_number) AS old_account_number,
    CASE (a.previous_product_code) WHEN 'HL' THEN '02' WHEN 'LAP' THEN '03' WHEN 'PL' THEN '05' WHEN 'AL' THEN '01' WHEN 'UCL' THEN '32' WHEN 'TWL' THEN '13' WHEN 'CVL' THEN '17' WHEN 'GL' THEN '07' WHEN 'EDU' THEN '08' WHEN 'CDL' THEN '06' WHEN 'BLU' THEN '61' WHEN 'BLS' THEN '50' WHEN 'MFP' THEN '41' WHEN 'MFB' THEN '40' WHEN 'KCC' THEN '36' WHEN 'LAS' THEN '04' WHEN 'LOC' THEN '37' WHEN 'CC' THEN '10' WHEN 'SCC' THEN '31' WHEN 'CCC' THEN '35' WHEN 'FLC' THEN '16' WHEN 'OD' THEN '12' ELSE (a.previous_product_code) END AS old_account_type,
    CASE (a.previous_party_role) WHEN 'PRIMARY' THEN '1' WHEN 'ADDON' THEN '2' WHEN 'GUARANTOR' THEN '3' WHEN 'JOINT' THEN '4' WHEN 'DECEASED' THEN '5' ELSE (a.previous_party_role) END AS old_ownership_indicator
FROM nbfc_001.account_details a
WHERE a.disbursement_date <= :as_of_date;
